  "paper\_id": "1804.06020",
  "title": "Improving Temporal Relation Extraction with a Globally Acquired Statistical Resource",
  "access": "full\_text",
  "research\_question": "Can large-scale corpus-derived prior knowledge about the temporal ordering of event types improve local and globally constrained temporal-relation extraction?",
  "methodology": "The authors build TemProb by extracting verb-frame events and temporal relations from more than one million New York Times articles spanning 1987–2007, using semantic role labeling, learned temporal classifiers, and greedy transitive-closure inference. The resulting counts define prior distributions over temporal relations between pairs of semantic verb frames. They validate these priors against TimeBank-Dense and an EventCausality dataset, then inject the priors as features into local averaged-perceptron classifiers and as regularization terms in an ILP global inference model. Performance is evaluated using precision, recall, F1, temporal-awareness F-score, significance tests, and additional bootstrap stability analysis.",
  "key\_findings": [
   {
    "finding": "TemProb contains approximately 51,000 distinct verb semantic frames, 9.2 million verb-pair-relation entries, and up to about 80 million extracted temporal relations from the NYT corpus.",
    "evidence\_type": "supported",
    "section": "3 TemProb"
   },
   {
    "finding": "TemProb's before/after probabilities behave as meaningful confidence estimates on TimeBank-Dense: increasing the probability threshold raises precision while reducing recall.",
    "evidence\_type": "supported",
    "section": "4.1 Quality Analysis of TemProb"
   },
   {
    "finding": "On the converted EventCausality evaluation, using TemProb priors achieved 66.2% accuracy, an 11.5-point improvement over the majority T-Before baseline.",
    "evidence\_type": "supported",
    "section": "4.1 Quality Analysis of TemProb"
   },
   {
    "finding": "Adding the full TemProb prior distribution as local classifier features improved F1 by 2.7 points for same-sentence relations and 6.5 points for adjacent-sentence relations relative to the original local features.",
    "evidence\_type": "supported",
    "section": "4.2.1 Improving Local Methods"
   },
   {
    "finding": "Combining TemProb features and ILP regularization increased global TimeBank-Dense F1 from 46.2 to 52.1 and temporal-awareness F-score from 42.5 to 49.6, with the reported comparison significant at p<0.0005.",
    "evidence\_type": "supported",
    "section": "4.2.2 Improving Global Methods"
   },
